.FSCORE_ITEM_KEYS <- c(
  "獲利性 (ROA > 0)" = "fscore_item_roa_pos",
  "獲利性 (OCF > 0)" = "fscore_item_ocf_pos",
  "獲利性 (ROA 成長)" = "fscore_item_roa_up",
